/// One natural person's authority to act as Authorizing Principal for the Context
/// Subject (HCP 17.2). The Authorization Service establishes it and the provider holds
/// its record; neither the Context Subject nor the delegate may change it, and a
/// change is a new delegation (HCP 17.2).
class Delegation {
  const Delegation({
    required this.delegationId,
    required this.subject,
    required this.delegate,
    required this.relationship,
    required this.basis,
    required this.scope,
    required this.term,
    this.mayDelegate,
    this.ended,
  });

  /// Read this payload from a decoded JSON object.
  factory Delegation.fromJson(Map<String, dynamic> json) => Delegation(
        delegationId: json['delegationId'] as String,
        subject:
            DelegationSubject.fromJson(json['subject'] as Map<String, dynamic>),
        delegate: DelegationDelegate.fromJson(
            json['delegate'] as Map<String, dynamic>),
        relationship: json['relationship'] as String,
        basis: DelegationBasis.fromJson(json['basis'] as Map<String, dynamic>),
        scope: DelegationScope.fromJson(json['scope'] as Map<String, dynamic>),
        term: DelegationTerm.fromJson(json['term'] as Map<String, dynamic>),
        mayDelegate: json['mayDelegate'] as bool?,
        ended: json['ended'] == null
            ? null
            : DelegationEnded.fromJson(json['ended'] as Map<String, dynamic>),
      );

  /// Stable for the life of the delegation; named by every grant issued under it and by
  /// audit events (HCP 17.2).
  final Urn delegationId;

  /// The Context Subject (HCP 17.2).
  final DelegationSubject subject;

  /// The delegate: a natural person, with a name the Context Subject can recognize (HCP
  /// 17.1, 17.2).
  final DelegationDelegate delegate;

  /// The delegate's relationship to the Context Subject: a value registered in HCP A.1
  /// (`parent-or-guardian`, `legal-guardian`, `attorney-in-fact`, `caregiver`) or an
  /// absolute URI. It confers nothing by itself; `scope` sets what the delegate may do
  /// (HCP 17.2). Distinct from an entry's reserved `subject.relationship` (HCP 11.3).
  /// The pattern admits the slug or an absolute URI's outline only: it carries no
  /// `format: uri`, which would refuse every slug, so checking that a custom value is a
  /// well-formed absolute URI, as HCP's prose requires (HCP A.3), is the consumer's
  /// check.
  final String relationship;

  /// What the authority rests on, and how the Authorization Service established it (HCP
  /// 17.3).
  final DelegationBasis basis;

  /// The categories and actions the delegate may authorize (HCP 17.4).
  final DelegationScope scope;

  /// When the delegation ends (HCP 17.2).
  final DelegationTerm term;

  /// True where the delegate may appoint a sub-delegate (HCP 17.10). Absent means false.
  /// Recorded by the Authorization Service (HCP 17.2).
  final bool? mayDelegate;

  /// Absent while the delegation holds; set when it ends, with the reason (HCP 17.6).
  final DelegationEnded? ended;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'delegationId': delegationId,
        'subject': subject.toJson(),
        'delegate': delegate.toJson(),
        'relationship': relationship,
        'basis': basis.toJson(),
        'scope': scope.toJson(),
        'term': term.toJson(),
        if (mayDelegate != null) 'mayDelegate': mayDelegate!,
        if (ended != null) 'ended': ended!.toJson(),
      };
}

/// A participant named by its identifier (HCP 8.2).
class AuditParty {
  const AuditParty({
    required this.id,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditParty.fromJson(Map<String, dynamic> json) => AuditParty(
        id: json['id'] as String,
      );

  /// The participant's identifier. The minLength and maxLength are framework bounds, not
  /// HCP requirements.
  final String id;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'id': id,
      };
}

/// Their role (HCP 8.2). HCP's own values, carried verbatim.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const AuditParticipantsInitiatorRole(String value) {
  static const AuditParticipantsInitiatorRole managementClient =
      AuditParticipantsInitiatorRole('management-client');
  static const AuditParticipantsInitiatorRole contextClient =
      AuditParticipantsInitiatorRole('context-client');
  static const AuditParticipantsInitiatorRole authorizationService =
      AuditParticipantsInitiatorRole('authorization-service');
  static const AuditParticipantsInitiatorRole hcpProvider =
      AuditParticipantsInitiatorRole('hcp-provider');

  /// Every value this specification's schema permits.
  static const List<AuditParticipantsInitiatorRole> values =
      <AuditParticipantsInitiatorRole>[
    managementClient,
    contextClient,
    authorizationService,
    hcpProvider
  ];
}

/// Who initiated the event.
class AuditParticipantsInitiator {
  const AuditParticipantsInitiator({
    required this.role,
    required this.id,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditParticipantsInitiator.fromJson(Map<String, dynamic> json) =>
      AuditParticipantsInitiator(
        role: AuditParticipantsInitiatorRole(json['role'] as String),
        id: json['id'] as String,
      );

  /// Their role (HCP 8.2). HCP's own values, carried verbatim.
  final AuditParticipantsInitiatorRole role;

  /// Their identifier. The minLength and maxLength are framework bounds, not HCP
  /// requirements.
  final String id;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'role': role.value,
        'id': id,
      };
}

/// The participants in an audit event (HCP 8.2, 3.9). No event names "system" (HCP
/// 8.2).
class AuditParticipants {
  const AuditParticipants({
    required this.initiator,
    this.clientOperator,
    this.requestingParty,
    this.authorizingPrincipal,
    required this.provider,
    this.retrievalId,
    this.model,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditParticipants.fromJson(Map<String, dynamic> json) =>
      AuditParticipants(
        initiator: AuditParticipantsInitiator.fromJson(
            json['initiator'] as Map<String, dynamic>),
        clientOperator: json['clientOperator'] == null
            ? null
            : AuditParty.fromJson(
                json['clientOperator'] as Map<String, dynamic>),
        requestingParty: json['requestingParty'] == null
            ? null
            : AuditParty.fromJson(
                json['requestingParty'] as Map<String, dynamic>),
        authorizingPrincipal: json['authorizingPrincipal'] == null
            ? null
            : AuditParty.fromJson(
                json['authorizingPrincipal'] as Map<String, dynamic>),
        provider: AuditParty.fromJson(json['provider'] as Map<String, dynamic>),
        retrievalId: json['retrievalId'] as String?,
        model: json['model'] == null
            ? null
            : AuditParty.fromJson(json['model'] as Map<String, dynamic>),
      );

  /// Who initiated the event.
  final AuditParticipantsInitiator initiator;

  /// The Client Operator, where a client took part (HCP 3.9).
  final AuditParty? clientOperator;

  /// The Requesting Party, where there is one (HCP 3.9).
  final AuditParty? requestingParty;

  /// The Authorizing Principal (HCP 3.9).
  final AuditParty? authorizingPrincipal;

  /// The HCP Provider (HCP 8.2).
  final AuditParty provider;

  /// The retrieval, on a read (HCP 8.2).
  final Urn? retrievalId;

  /// The model, where one took part (HCP 3.9).
  final AuditParty? model;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'initiator': initiator.toJson(),
        if (clientOperator != null) 'clientOperator': clientOperator!.toJson(),
        if (requestingParty != null)
          'requestingParty': requestingParty!.toJson(),
        if (authorizingPrincipal != null)
          'authorizingPrincipal': authorizingPrincipal!.toJson(),
        'provider': provider.toJson(),
        if (retrievalId != null) 'retrievalId': retrievalId!,
        if (model != null) 'model': model!.toJson(),
      };
}

/// Where a credential was disclosed in derived form, the evidence item and the claims
/// revealed (HCP 14.9).
class AuditDisclosedRevealedItem {
  const AuditDisclosedRevealedItem({
    required this.evidence,
    required this.claims,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditDisclosedRevealedItem.fromJson(Map<String, dynamic> json) =>
      AuditDisclosedRevealedItem(
        evidence: json['evidence'] as int,
        claims:
            (json['claims'] as List<dynamic>).map((e) => e as String).toList(),
      );

  /// The evidence item's index.
  final int evidence;

  /// The claims revealed, each a JSON Pointer. The maxItems and maxLength are framework
  /// bounds, not HCP requirements.
  final List<String> claims;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'evidence': evidence,
        'claims': claims,
      };
}

/// One entry a retrieval disclosed (HCP 8.2).
class AuditDisclosed {
  const AuditDisclosed({
    required this.entryId,
    required this.version,
    required this.useUntil,
    this.provenance,
    this.revealed,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditDisclosed.fromJson(Map<String, dynamic> json) => AuditDisclosed(
        entryId: json['entryId'] as String,
        version: json['version'] as int,
        useUntil: json['useUntil'] as String,
        provenance: json['provenance'] as bool?,
        revealed: json['revealed'] == null
            ? null
            : (json['revealed'] as List<dynamic>)
                .map((e) => AuditDisclosedRevealedItem.fromJson(
                    e as Map<String, dynamic>))
                .toList(),
      );

  /// The entry's stable `id`.
  final Urn entryId;

  /// The version disclosed.
  final int version;

  /// The use-until time the disclosure was given (HCP 7.6).
  final Instant useUntil;

  /// True where the disclosure carried provenance (HCP 7.4.1); omitted otherwise.
  final bool? provenance;

  /// Present only where a credential was disclosed in derived form (HCP 8.2, 14.9). The
  /// maxItems is a framework bound, not an HCP requirement.
  final List<AuditDisclosedRevealedItem>? revealed;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'entryId': entryId,
        'version': version,
        'useUntil': useUntil,
        if (provenance != null) 'provenance': provenance!,
        if (revealed != null)
          'revealed': revealed!.map((e) => e.toJson()).toList(),
      };
}

/// One audit event (HCP 8.2). The log names entries by their stable `id`, never by the
/// `ref` a client received, because the log is the Context Subject's (HCP 8.2, 8.3).
/// The query text is never recorded (HCP 8.2). `entryId`, `relatedEntryId`, `purpose`,
/// `purposeDescription` and `grantId` are required, each a value or null, as HCP 8.2's
/// template writes them: HCP's own shape leaves them optional, and the carriage
/// requires them so that a null always travels and is never confused with an absent
/// member, pending HCP confirmation (question 42). An event redacted for a former
/// delegate carries `entryId` and `relatedEntryId` as null (HCP 17.7).
class AuditEvent {
  const AuditEvent({
    required this.eventId,
    required this.eventType,
    required this.timestamp,
    required this.participants,
    this.entryId,
    this.relatedEntryId,
    this.categories,
    this.purpose,
    this.purposeDescription,
    this.grantId,
    this.disclosed,
    this.data,
  });

  /// Read this payload from a decoded JSON object.
  factory AuditEvent.fromJson(Map<String, dynamic> json) => AuditEvent(
        eventId: json['eventId'] as String,
        eventType: json['eventType'] as String,
        timestamp: json['timestamp'] as String,
        participants: AuditParticipants.fromJson(
            json['participants'] as Map<String, dynamic>),
        entryId: json['entryId'] as String?,
        relatedEntryId: json['relatedEntryId'] as String?,
        categories: json['categories'] == null
            ? null
            : (json['categories'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        purpose: json['purpose'] as String?,
        purposeDescription: json['purposeDescription'] as String?,
        grantId: json['grantId'] as String?,
        disclosed: json['disclosed'] == null
            ? null
            : (json['disclosed'] as List<dynamic>)
                .map((e) => AuditDisclosed.fromJson(e as Map<String, dynamic>))
                .toList(),
        data: json['data'] as Map<String, dynamic>?,
      );

  /// The event's identifier (HCP 8.2).
  final Urn eventId;

  /// The event type, one of those HCP 8.1 lists (such as `context.read`,
  /// `grant.revoked`, `rule.set`). Left open, as HCP's own shape leaves it, so that the
  /// event types of a later draft are not refused. The minLength and maxLength are
  /// framework bounds, not HCP requirements.
  final String eventType;

  /// When the event occurred. HCP's member name (HCP 8.2), carried verbatim so the event
  /// is the one an export carries (HCP 5.4.1).
  final Instant timestamp;

  /// Who took part (HCP 8.2, 3.9).
  final AuditParticipants participants;

  /// The entry concerned, by its `id`, or null where the event concerns none (HCP 8.2).
  /// For conflict events, the conflicted entry (HCP 8.2). Required, and null in an event
  /// redacted for a former delegate (HCP 17.7), pending HCP confirmation (question 42).
  final String? entryId;

  /// For conflict events, the authoritative entry (or the other entry where neither or
  /// both are authoritative); null for every other event type (HCP 8.2). Required, and
  /// null in an event redacted for a former delegate (HCP 17.7), pending HCP
  /// confirmation (question 42).
  final String? relatedEntryId;

  /// The categories concerned (HCP 8.2). The maxItems is a framework bound, not an HCP
  /// requirement.
  final List<Category>? categories;

  /// The purpose code stated, an absolute URI with the same shape as `PurposeCode` in
  /// common.schema.json (HCP's `anyOf \[purposeCode, null\]`), or null where none was (HCP
  /// 8.2, 6.1.5.2). `format` constrains only a string, so null still passes. Required,
  /// pending HCP confirmation (question 42). The minLength and maxLength are framework
  /// bounds, not HCP requirements.
  final String? purpose;

  /// The stated task, or null where none was stated (HCP 8.2). Required, pending HCP
  /// confirmation (question 42). The maxLength is a framework bound, not an HCP
  /// requirement.
  final String? purposeDescription;

  /// The grant concerned, or null where the event concerns none (HCP 8.2). Required,
  /// pending HCP confirmation (question 42).
  final String? grantId;

  /// Present on `context.read`: every entry the retrieval disclosed (HCP 8.2). A
  /// retrieval discloses at most 20 entries (HCP 7.2).
  final List<AuditDisclosed>? disclosed;

  /// The members HCP 8.2 fixes for the event type, such as `options` for
  /// `context.exported` or `ruleId` for `rule.set`. Implementations may add members,
  /// which are preserved and not interpreted (HCP 8.2, A.3).
  final Map<String, dynamic>? data;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'eventId': eventId,
        'eventType': eventType,
        'timestamp': timestamp,
        'participants': participants.toJson(),
        if (entryId != null) 'entryId': entryId!,
        if (relatedEntryId != null) 'relatedEntryId': relatedEntryId!,
        if (categories != null) 'categories': categories!,
        if (purpose != null) 'purpose': purpose!,
        if (purposeDescription != null)
          'purposeDescription': purposeDescription!,
        if (grantId != null) 'grantId': grantId!,
        if (disclosed != null)
          'disclosed': disclosed!.map((e) => e.toJson()).toList(),
        if (data != null) 'data': data!,
      };
}

/// The Context Subject (HCP 5.4.1).
class ExportSubject {
  const ExportSubject({
    required this.id,
  });

  /// Read this payload from a decoded JSON object.
  factory ExportSubject.fromJson(Map<String, dynamic> json) => ExportSubject(
        id: json['id'] as String,
      );

  /// The Context Subject's identifier.
  final String id;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'id': id,
      };
}

/// An HCP export: a JSON-LD document holding the Context Subject's entries and their
/// standing rules, directives and delegations, and optionally superseded versions and
/// the audit log (HCP 5.4.1). Entries removed by hard deletion are never in it (HCP
/// 5.4.1). The maxItems bounds are framework bounds, not HCP requirements: HCP sets
/// none. Those on `rules`, `directives` and `delegations` are set so that the
/// document's `maxDocumentBytes` (14 MiB for an hcp/export response, 16 MiB for an
/// hcp/import request) is reached first (each item serializes to more than 100 bytes),
/// as HCP 5.4.1 lists every rule, directive and delegation and the list operations
/// bound none: an export too large for one document is refused with
/// `hcp/export:tooLarge` (hcp/export), never cut short by an item count.
class Export {
  const Export({
    required this.context,
    required this.type,
    required this.schema,
    required this.subject,
    required this.exportedBy,
    required this.exportedAt,
    required this.options,
    required this.entries,
    this.versions,
    required this.rules,
    this.directives,
    this.delegations,
    this.audit,
  });

  /// Read this payload from a decoded JSON object.
  factory Export.fromJson(Map<String, dynamic> json) => Export(
        context: json['@context'],
        type: json['type'] as String,
        schema: json['schema'] as String,
        subject:
            ExportSubject.fromJson(json['subject'] as Map<String, dynamic>),
        exportedBy: json['exportedBy'] as String,
        exportedAt: json['exportedAt'] as String,
        options:
            ExportOptions.fromJson(json['options'] as Map<String, dynamic>),
        entries: (json['entries'] as List<dynamic>)
            .map((e) => e as Map<String, dynamic>)
            .toList(),
        versions: json['versions'] == null
            ? null
            : (json['versions'] as List<dynamic>)
                .map((e) => e as Map<String, dynamic>)
                .toList(),
        rules: (json['rules'] as List<dynamic>)
            .map((e) => StandingRule.fromJson(e as Map<String, dynamic>))
            .toList(),
        directives: json['directives'] == null
            ? null
            : (json['directives'] as List<dynamic>)
                .map((e) => Directive.fromJson(e as Map<String, dynamic>))
                .toList(),
        delegations: json['delegations'] == null
            ? null
            : (json['delegations'] as List<dynamic>)
                .map((e) => Delegation.fromJson(e as Map<String, dynamic>))
                .toList(),
        audit: json['audit'] == null
            ? null
            : (json['audit'] as List<dynamic>)
                .map((e) => AuditEvent.fromJson(e as Map<String, dynamic>))
                .toList(),
      );

  /// The export's JSON-LD context, `https://hcp.example/contexts/v2` in HCP 2.0-draft-3
  /// (HCP 5.4.1). As an array, at most 16 items: a framework bound, not an HCP
  /// requirement.
  final Object? context;

  /// `ContextExport` (HCP 5.4.1). HCP's own value, carried verbatim.
  final String type;

  /// The export structure version, compared as an exact string (HCP 5.4.1, 1.7).
  final String schema;

  /// The Context Subject (HCP 5.4.1).
  final ExportSubject subject;

  /// The exporting HCP Provider (HCP 5.4.1).
  final String exportedBy;

  /// When the export was made (HCP 5.4.1).
  final Instant exportedAt;

  /// The options requested (HCP 5.4.1). Required, with `includeVersions` and
  /// `includeAudit`, so that the export itself says whether `versions` and `audit` were
  /// requested: an empty or absent `versions` or `audit` under a true option means
  /// requested and none, under a false one not requested. HCP's own shape leaves
  /// `options` optional, and hcp/import accepts an export without it; requiring it of an
  /// export the provider produces is pending HCP confirmation (question 42).
  final ExportOptions options;

  /// The current version of each entry exported, whatever its `record.status` (HCP
  /// 5.4.1). An export a provider writes carries each in the form of HCP 4.2 (see
  /// context-entry.schema.json `Entry`); an import accepts entries in any schema the
  /// importing provider accepts, including HCP v1 forms (HCP 5.4.3, 4.3), so items are
  /// left open here, as in HCP's own shape, and each is validated against the schema it
  /// names.
  final List<Map<String, dynamic>> entries;

  /// Superseded versions, each in the form of HCP 4.2. Present only where requested (HCP
  /// 5.4.1), which `options.includeVersions` records.
  final List<Map<String, dynamic>>? versions;

  /// The Context Subject's standing rules (HCP 5.4.1, 6.3).
  final List<StandingRule> rules;

  /// The Context Subject's directives (HCP 5.4.1, 6.4).
  final List<Directive>? directives;

  /// The delegations made for the Context Subject, ended ones included, as a record. An
  /// import does not establish them (HCP 5.4.1, 17.2).
  final List<Delegation>? delegations;

  /// The audit log, as events in the structure of HCP 8.2. Present only where requested
  /// (HCP 5.4.1), which `options.includeAudit` records.
  final List<AuditEvent>? audit;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        '@context': context,
        'type': type,
        'schema': schema,
        'subject': subject.toJson(),
        'exportedBy': exportedBy,
        'exportedAt': exportedAt,
        'options': options.toJson(),
        'entries': entries,
        if (versions != null) 'versions': versions!,
        'rules': rules.map((e) => e.toJson()).toList(),
        if (directives != null)
          'directives': directives!.map((e) => e.toJson()).toList(),
        if (delegations != null)
          'delegations': delegations!.map((e) => e.toJson()).toList(),
        if (audit != null) 'audit': audit!.map((e) => e.toJson()).toList(),
      };
}

/// The Context Subject's export (HCP 5.4.1). HCP's HTTP Binding answers with the
/// export document itself as the body (HCP 9.4.8); this payload wraps it, unchanged,
/// in the one member `export`, so that the payload stays closed while the export, like
/// HCP's own shape, stays open. Failures use trust-task-error, not this shape.
class Response {
  const Response({
    required this.export,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        export: Export.fromJson(json['export'] as Map<String, dynamic>),
      );

  /// The HCP export document (HCP 5.4.1), unchanged: the current version of every entry
  /// not hard-deleted, whatever its status, unless `excludeDeleted` was asked; the
  /// standing rules, directives and delegations; and superseded versions and the audit
  /// log where asked. Its `options` records the options used.
  final Export export;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'export': export.toJson(),
      };
}

/// The request payload of the HCP 2.0-draft-3 Export operation (HCP 5.4.1, 5.4; `GET
/// /v2/export` in HCP 9.4.8): a Management Client, acting for the Context Subject,
/// asks the provider for the Context Subject's own export. HCP defines no request
/// schema for this operation; the members are HCP 5.4.1's export options, which HCP
/// 9.4.8 carries as query parameters. The outer document members (id, type, issuer,
/// recipient, issuedAt, expiresAt, proof) are owned by the framework — SPEC §6.3.
/// Every maxLength, maxItems and maxProperties in this schema is a Trust Tasks
/// framework bound (SPEC §7.3 item 19), not an HCP requirement; so is every minLength
/// or minItems of 1 on a member HCP's own schema allows to be empty.
class Payload {
  const Payload({
    this.excludeDeleted,
    this.includeVersions,
    this.includeAudit,
    this.accessToken,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        excludeDeleted: json['excludeDeleted'] as bool?,
        includeVersions: json['includeVersions'] as bool?,
        includeAudit: json['includeAudit'] as bool?,
        accessToken: json['accessToken'] as String?,
      );

  /// HCP's "excluding deleted entries" export option (HCP 5.4.1), `exclude=deleted` in
  /// HCP 9.4.8: omit entries whose `record.status` is `deleted`. Absent or false means
  /// deleted entries are exported, as HCP's default requires.
  final bool? excludeDeleted;

  /// HCP's "including versions" export option (HCP 5.4.1), `include=versions` in HCP
  /// 9.4.8: also return the superseded versions of each entry returned. Absent or false
  /// means the current version only.
  final bool? includeVersions;

  /// HCP's "including the audit log" export option (HCP 5.4.1, 8.3), `include=audit` in
  /// HCP 9.4.8: also return the Context Subject's audit log in the structure of HCP 8.2.
  /// Absent or false means no audit log.
  final bool? includeAudit;

  /// The Management Client's HCP access token (HCP 9.3), carried unchanged. HCP's HTTP
  /// Binding sends it as a Bearer token; this member carries it in the document. The
  /// provider validates it exactly as over HTTP and treats it as opaque. The maxLength
  /// is a framework bound, not an HCP requirement. OPTIONAL: where it is absent, the
  /// provider authenticates the request's `issuer` VID, by the REQUIRED request proof,
  /// as a Management Client the Authorizing Principal enrolled (HCP 3.2.3), and refuses
  /// any other issuer with permissionDenied; where it is present, the token rules apply
  /// unchanged. Pending HCP confirmation (question 56).
  final String? accessToken;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (excludeDeleted != null) 'excludeDeleted': excludeDeleted!,
        if (includeVersions != null) 'includeVersions': includeVersions!,
        if (includeAudit != null) 'includeAudit': includeAudit!,
        if (accessToken != null) 'accessToken': accessToken!,
      };
}

