const String payloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$id":"https://trusttasks.org/spec/hcp/export/0.1","title":"HCP — Export — payload","description":"The request payload of the HCP 2.0-draft-3 Export operation (HCP 5.4.1, 5.4; `GET /v2/export` in HCP 9.4.8): a Management Client, acting for the Context Subject, asks the provider for the Context Subject\'s own export. HCP defines no request schema for this operation; the members are HCP 5.4.1\'s export options, which HCP 9.4.8 carries as query parameters. The outer document members (id, type, issuer, recipient, issuedAt, expiresAt, proof) are owned by the framework — SPEC §6.3. Every maxLength, maxItems and maxProperties in this schema is a Trust Tasks framework bound (SPEC §7.3 item 19), not an HCP requirement; so is every minLength or minItems of 1 on a member HCP\'s own schema allows to be empty.","type":"object","additionalProperties":false,"properties":{"excludeDeleted":{"type":"boolean","description":"HCP\'s \\"excluding deleted entries\\" export option (HCP 5.4.1), `exclude=deleted` in HCP 9.4.8: omit entries whose `record.status` is `deleted`. Absent or false means deleted entries are exported, as HCP\'s default requires."},"includeVersions":{"type":"boolean","description":"HCP\'s \\"including versions\\" export option (HCP 5.4.1), `include=versions` in HCP 9.4.8: also return the superseded versions of each entry returned. Absent or false means the current version only."},"includeAudit":{"type":"boolean","description":"HCP\'s \\"including the audit log\\" export option (HCP 5.4.1, 8.3), `include=audit` in HCP 9.4.8: also return the Context Subject\'s audit log in the structure of HCP 8.2. Absent or false means no audit log."},"accessToken":{"type":"string","minLength":1,"maxLength":8192,"description":"The Management Client\'s HCP access token (HCP 9.3), carried unchanged. HCP\'s HTTP Binding sends it as a Bearer token; this member carries it in the document. The provider validates it exactly as over HTTP and treats it as opaque. The maxLength is a framework bound, not an HCP requirement. OPTIONAL: where it is absent, the provider authenticates the request\'s `issuer` VID, by the REQUIRED request proof, as a Management Client the Authorizing Principal enrolled (HCP 3.2.3), and refuses any other issuer with permissionDenied; where it is present, the token rules apply unchanged. Pending HCP confirmation (question 56)."}}}';

