const String responsePayloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"HCP — Export — response payload","type":"object","additionalProperties":false,"required":["export"],"description":"The Context Subject\'s export (HCP 5.4.1). HCP\'s HTTP Binding answers with the export document itself as the body (HCP 9.4.8); this payload wraps it, unchanged, in the one member `export`, so that the payload stays closed while the export, like HCP\'s own shape, stays open. Failures use trust-task-error, not this shape.","properties":{"export":{"\$ref":"#/\$defs/Export","description":"The HCP export document (HCP 5.4.1), unchanged: the current version of every entry not hard-deleted, whatever its status, unless `excludeDeleted` was asked; the standing rules, directives and delegations; and superseded versions and the audit log where asked. Its `options` records the options used."}}},"Export":{"type":"object","additionalProperties":true,"required":["@context","type","schema","subject","exportedBy","exportedAt","options","entries","rules"],"description":"An HCP export: a JSON-LD document holding the Context Subject\'s entries and their standing rules, directives and delegations, and optionally superseded versions and the audit log (HCP 5.4.1). Entries removed by hard deletion are never in it (HCP 5.4.1). The maxItems bounds are framework bounds, not HCP requirements: HCP sets none. Those on `rules`, `directives` and `delegations` are set so that the document\'s `maxDocumentBytes` (14 MiB for an hcp/export response, 16 MiB for an hcp/import request) is reached first (each item serializes to more than 100 bytes), as HCP 5.4.1 lists every rule, directive and delegation and the list operations bound none: an export too large for one document is refused with `hcp/export:tooLarge` (hcp/export), never cut short by an item count.","properties":{"@context":{"type":["array","string"],"maxItems":16,"description":"The export\'s JSON-LD context, `https://hcp.example/contexts/v2` in HCP 2.0-draft-3 (HCP 5.4.1). As an array, at most 16 items: a framework bound, not an HCP requirement."},"type":{"type":"string","const":"ContextExport","description":"`ContextExport` (HCP 5.4.1). HCP\'s own value, carried verbatim."},"schema":{"type":"string","const":"https://hcp.example/spec/export/2.0","description":"The export structure version, compared as an exact string (HCP 5.4.1, 1.7)."},"subject":{"type":"object","additionalProperties":true,"required":["id"],"description":"The Context Subject (HCP 5.4.1).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"The Context Subject\'s identifier."}}},"exportedBy":{"type":"string","minLength":1,"maxLength":2048,"description":"The exporting HCP Provider (HCP 5.4.1)."},"exportedAt":{"\$ref":"#/\$defs/Instant","description":"When the export was made (HCP 5.4.1)."},"options":{"\$ref":"#/\$defs/ExportOptions","description":"The options requested (HCP 5.4.1). Required, with `includeVersions` and `includeAudit`, so that the export itself says whether `versions` and `audit` were requested: an empty or absent `versions` or `audit` under a true option means requested and none, under a false one not requested. HCP\'s own shape leaves `options` optional, and hcp/import accepts an export without it; requiring it of an export the provider produces is pending HCP confirmation (question 42)."},"entries":{"type":"array","maxItems":100000,"items":{"type":"object","additionalProperties":true},"description":"The current version of each entry exported, whatever its `record.status` (HCP 5.4.1). An export a provider writes carries each in the form of HCP 4.2 (see context-entry.schema.json `Entry`); an import accepts entries in any schema the importing provider accepts, including HCP v1 forms (HCP 5.4.3, 4.3), so items are left open here, as in HCP\'s own shape, and each is validated against the schema it names."},"versions":{"type":"array","maxItems":1000000,"items":{"type":"object","additionalProperties":true},"description":"Superseded versions, each in the form of HCP 4.2. Present only where requested (HCP 5.4.1), which `options.includeVersions` records."},"rules":{"type":"array","maxItems":1000000,"items":{"\$ref":"#/\$defs/StandingRule"},"description":"The Context Subject\'s standing rules (HCP 5.4.1, 6.3)."},"directives":{"type":"array","maxItems":1000000,"items":{"\$ref":"#/\$defs/Directive"},"description":"The Context Subject\'s directives (HCP 5.4.1, 6.4)."},"delegations":{"type":"array","maxItems":1000000,"items":{"\$ref":"#/\$defs/Delegation"},"description":"The delegations made for the Context Subject, ended ones included, as a record. An import does not establish them (HCP 5.4.1, 17.2)."},"audit":{"type":"array","maxItems":1000000,"items":{"\$ref":"#/\$defs/AuditEvent"},"description":"The audit log, as events in the structure of HCP 8.2. Present only where requested (HCP 5.4.1), which `options.includeAudit` records."}}},"ExportOptions":{"type":"object","additionalProperties":true,"required":["includeVersions","includeAudit"],"description":"The export options used (HCP 5.4.1). `includeVersions` and `includeAudit` are required, true where the option was requested and false otherwise, pending HCP confirmation (question 42); `excludeDeleted` absent or false means the default.","properties":{"excludeDeleted":{"type":"boolean","description":"Omit entries whose `record.status` is `deleted` (HCP 5.4.1)."},"includeVersions":{"type":"boolean","description":"Also return superseded versions of each entry returned (HCP 5.4.1)."},"includeAudit":{"type":"boolean","description":"Also return the Context Subject\'s audit log (HCP 5.4.1, 8.3)."}}},"AuditEvent":{"type":"object","additionalProperties":true,"required":["eventId","eventType","timestamp","participants","entryId","relatedEntryId","purpose","purposeDescription","grantId"],"description":"One audit event (HCP 8.2). The log names entries by their stable `id`, never by the `ref` a client received, because the log is the Context Subject\'s (HCP 8.2, 8.3). The query text is never recorded (HCP 8.2). `entryId`, `relatedEntryId`, `purpose`, `purposeDescription` and `grantId` are required, each a value or null, as HCP 8.2\'s template writes them: HCP\'s own shape leaves them optional, and the carriage requires them so that a null always travels and is never confused with an absent member, pending HCP confirmation (question 42). An event redacted for a former delegate carries `entryId` and `relatedEntryId` as null (HCP 17.7).","properties":{"eventId":{"\$ref":"#/\$defs/Urn","description":"The event\'s identifier (HCP 8.2)."},"eventType":{"type":"string","minLength":1,"maxLength":256,"description":"The event type, one of those HCP 8.1 lists (such as `context.read`, `grant.revoked`, `rule.set`). Left open, as HCP\'s own shape leaves it, so that the event types of a later draft are not refused. The minLength and maxLength are framework bounds, not HCP requirements."},"timestamp":{"\$ref":"#/\$defs/Instant","description":"When the event occurred. HCP\'s member name (HCP 8.2), carried verbatim so the event is the one an export carries (HCP 5.4.1)."},"participants":{"\$ref":"#/\$defs/AuditParticipants","description":"Who took part (HCP 8.2, 3.9)."},"entryId":{"type":["string","null"],"pattern":"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$","description":"The entry concerned, by its `id`, or null where the event concerns none (HCP 8.2). For conflict events, the conflicted entry (HCP 8.2). Required, and null in an event redacted for a former delegate (HCP 17.7), pending HCP confirmation (question 42)."},"relatedEntryId":{"type":["string","null"],"pattern":"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$","description":"For conflict events, the authoritative entry (or the other entry where neither or both are authoritative); null for every other event type (HCP 8.2). Required, and null in an event redacted for a former delegate (HCP 17.7), pending HCP confirmation (question 42)."},"categories":{"type":"array","maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories concerned (HCP 8.2). The maxItems is a framework bound, not an HCP requirement."},"purpose":{"type":["string","null"],"format":"uri","minLength":1,"maxLength":2048,"pattern":"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+\$","description":"The purpose code stated, an absolute URI with the same shape as `PurposeCode` in common.schema.json (HCP\'s `anyOf [purposeCode, null]`), or null where none was (HCP 8.2, 6.1.5.2). `format` constrains only a string, so null still passes. Required, pending HCP confirmation (question 42). The minLength and maxLength are framework bounds, not HCP requirements."},"purposeDescription":{"type":["string","null"],"maxLength":4096,"description":"The stated task, or null where none was stated (HCP 8.2). Required, pending HCP confirmation (question 42). The maxLength is a framework bound, not an HCP requirement."},"grantId":{"type":["string","null"],"pattern":"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$","description":"The grant concerned, or null where the event concerns none (HCP 8.2). Required, pending HCP confirmation (question 42)."},"disclosed":{"type":"array","maxItems":20,"items":{"\$ref":"#/\$defs/AuditDisclosed"},"description":"Present on `context.read`: every entry the retrieval disclosed (HCP 8.2). A retrieval discloses at most 20 entries (HCP 7.2)."},"data":{"type":"object","additionalProperties":true,"description":"The members HCP 8.2 fixes for the event type, such as `options` for `context.exported` or `ruleId` for `rule.set`. Implementations may add members, which are preserved and not interpreted (HCP 8.2, A.3)."}}},"AuditDisclosed":{"type":"object","additionalProperties":true,"required":["entryId","version","useUntil"],"description":"One entry a retrieval disclosed (HCP 8.2).","properties":{"entryId":{"\$ref":"#/\$defs/Urn","description":"The entry\'s stable `id`."},"version":{"type":"integer","minimum":1,"description":"The version disclosed."},"useUntil":{"\$ref":"#/\$defs/Instant","description":"The use-until time the disclosure was given (HCP 7.6)."},"provenance":{"type":"boolean","description":"True where the disclosure carried provenance (HCP 7.4.1); omitted otherwise."},"revealed":{"type":"array","maxItems":16,"items":{"type":"object","additionalProperties":true,"required":["evidence","claims"],"description":"Where a credential was disclosed in derived form, the evidence item and the claims revealed (HCP 14.9).","properties":{"evidence":{"type":"integer","minimum":0,"description":"The evidence item\'s index."},"claims":{"type":"array","maxItems":256,"items":{"type":"string","maxLength":2048},"description":"The claims revealed, each a JSON Pointer. The maxItems and maxLength are framework bounds, not HCP requirements."}}},"description":"Present only where a credential was disclosed in derived form (HCP 8.2, 14.9). The maxItems is a framework bound, not an HCP requirement."}}},"Instant":{"type":"string","format":"date-time","description":"An RFC 3339 instant."},"Urn":{"type":"string","pattern":"^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$","description":"An HCP identifier: a UUID in `urn:uuid:` form, of any UUID version (HCP 4.2), as HCP uses for entry, grant, directive and retrieval identifiers."},"AuditParticipants":{"type":"object","additionalProperties":true,"required":["initiator","provider"],"description":"The participants in an audit event (HCP 8.2, 3.9). No event names \\"system\\" (HCP 8.2).","properties":{"initiator":{"type":"object","additionalProperties":true,"required":["role","id"],"description":"Who initiated the event.","properties":{"role":{"type":"string","enum":["management-client","context-client","authorization-service","hcp-provider"],"description":"Their role (HCP 8.2). HCP\'s own values, carried verbatim."},"id":{"type":"string","minLength":1,"maxLength":2048,"description":"Their identifier. The minLength and maxLength are framework bounds, not HCP requirements."}}},"clientOperator":{"\$ref":"#/\$defs/AuditParty","description":"The Client Operator, where a client took part (HCP 3.9)."},"requestingParty":{"\$ref":"#/\$defs/AuditParty","description":"The Requesting Party, where there is one (HCP 3.9)."},"authorizingPrincipal":{"\$ref":"#/\$defs/AuditParty","description":"The Authorizing Principal (HCP 3.9)."},"provider":{"\$ref":"#/\$defs/AuditParty","description":"The HCP Provider (HCP 8.2)."},"retrievalId":{"\$ref":"#/\$defs/Urn","description":"The retrieval, on a read (HCP 8.2)."},"model":{"\$ref":"#/\$defs/AuditParty","description":"The model, where one took part (HCP 3.9)."}}},"AuditParty":{"type":"object","additionalProperties":true,"required":["id"],"description":"A participant named by its identifier (HCP 8.2).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"The participant\'s identifier. The minLength and maxLength are framework bounds, not HCP requirements."}}},"Category":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^([a-z][a-z0-9_]*|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)\$","description":"An HCP context category (HCP 4.5), the primary unit of access control: either a slug from HCP\'s category registry, such as `general_preferences` or `health_context`, or a custom category written as an absolute URI under a domain its definer controls. A custom category is not portable between providers without bilateral agreement (HCP 4.5). The pattern admits the slug or an absolute URI\'s outline only: it carries no `format: uri`, which would refuse every slug, so checking that a custom value is a well-formed absolute URI, as HCP\'s prose requires (HCP A.3), is the consumer\'s check."},"Delegation":{"type":"object","additionalProperties":true,"required":["delegationId","subject","delegate","relationship","basis","scope","term"],"description":"One natural person\'s authority to act as Authorizing Principal for the Context Subject (HCP 17.2). The Authorization Service establishes it and the provider holds its record; neither the Context Subject nor the delegate may change it, and a change is a new delegation (HCP 17.2).","properties":{"delegationId":{"\$ref":"#/\$defs/Urn","description":"Stable for the life of the delegation; named by every grant issued under it and by audit events (HCP 17.2)."},"subject":{"type":"object","additionalProperties":true,"required":["id"],"description":"The Context Subject (HCP 17.2).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"The Context Subject\'s identifier."}}},"delegate":{"type":"object","additionalProperties":true,"required":["id","name"],"description":"The delegate: a natural person, with a name the Context Subject can recognize (HCP 17.1, 17.2).","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"description":"The delegate\'s identifier."},"name":{"type":"string","minLength":1,"maxLength":1024,"description":"A name the Context Subject can recognize."}}},"relationship":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^(parent-or-guardian|legal-guardian|attorney-in-fact|caregiver|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)\$","description":"The delegate\'s relationship to the Context Subject: a value registered in HCP A.1 (`parent-or-guardian`, `legal-guardian`, `attorney-in-fact`, `caregiver`) or an absolute URI. It confers nothing by itself; `scope` sets what the delegate may do (HCP 17.2). Distinct from an entry\'s reserved `subject.relationship` (HCP 11.3). The pattern admits the slug or an absolute URI\'s outline only: it carries no `format: uri`, which would refuse every slug, so checking that a custom value is a well-formed absolute URI, as HCP\'s prose requires (HCP A.3), is the consumer\'s check."},"basis":{"\$ref":"#/\$defs/DelegationBasis","description":"What the authority rests on, and how the Authorization Service established it (HCP 17.3)."},"scope":{"\$ref":"#/\$defs/DelegationScope","description":"The categories and actions the delegate may authorize (HCP 17.4)."},"term":{"\$ref":"#/\$defs/DelegationTerm","description":"When the delegation ends (HCP 17.2)."},"mayDelegate":{"type":"boolean","description":"True where the delegate may appoint a sub-delegate (HCP 17.10). Absent means false. Recorded by the Authorization Service (HCP 17.2)."},"ended":{"\$ref":"#/\$defs/DelegationEnded","description":"Absent while the delegation holds; set when it ends, with the reason (HCP 17.6)."}}},"DelegationEnded":{"type":"object","additionalProperties":true,"required":["at","reason"],"description":"How and when a delegation ended (HCP 17.6). The member name `at` is HCP\'s own, carried verbatim.","properties":{"at":{"\$ref":"#/\$defs/Instant","description":"When the delegation ended (HCP 17.2, 17.6)."},"reason":{"type":"string","enum":["majority","expiry","basis-ended","relinquished","ended-by-subject","parent-ended","ended-by-delegate"],"description":"Why it ended (HCP 17.6). HCP\'s own values, carried verbatim."}}},"DelegationTerm":{"type":"object","additionalProperties":true,"required":["endsAt","atMajority"],"description":"When a delegation ends: at `endsAt`, and at the Context Subject\'s age of majority where `atMajority` is true (HCP 17.2).","properties":{"endsAt":{"type":["string","null"],"format":"date-time","description":"When the delegation ends; null where no end is known (HCP 17.2)."},"atMajority":{"type":"boolean","description":"True where the delegation ends at the Context Subject\'s age of majority, which the Authorization Service determines under the law that applies (HCP 17.2)."}}},"DelegationScope":{"type":"object","additionalProperties":true,"required":["categories","actions"],"description":"The categories and actions a delegate may authorize; every category is named, with no wildcard (HCP 17.4).","properties":{"categories":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories in scope (HCP 17.4). The maxItems is a framework bound, not an HCP requirement."},"actions":{"type":"array","minItems":1,"maxItems":2,"uniqueItems":true,"items":{"type":"string","enum":["read","write"]},"description":"The actions in scope (HCP 17.2, 6.1.5)."}}},"DelegationBasis":{"type":"object","additionalProperties":true,"required":["method","description","establishedBy","establishedAt"],"description":"What a delegation\'s authority rests on (HCP 17.3). Where `method` is `evidence`, `evidence` is present with at least one item; `parent` is present exactly where `method` is `delegated` (HCP 17.3, 17.10). Those rules are not checked by the schema: the registry\'s Rust generator does not support `if`/`then`/`else`, so a validator does not check them.","properties":{"method":{"type":"string","enum":["appointed","attested","evidence","delegated","unspecified"],"description":"How the authority was established (HCP 17.3). `unspecified` is used only for a delegation converted from HCP v1 and MUST NOT be presented to anyone as `attested` (HCP 17.3, 17.8)."},"description":{"type":"string","minLength":1,"maxLength":4096,"description":"What the authority rests on, shown to the Context Subject and the delegate (HCP 17.3). The maxLength is a framework bound, not an HCP requirement."},"parent":{"\$ref":"#/\$defs/Urn","description":"For a sub-delegation (`method` `delegated`), the delegation it came from (HCP 17.10)."},"evidence":{"type":"array","maxItems":16,"items":{"\$ref":"#/\$defs/EvidenceItem"},"description":"The evidence presented, for `method` `evidence`: a credential of guardianship, a court order, a power of attorney. A Verifiable Credential is held whole, as an entry\'s evidence item is (HCP 17.3, 4.2.2). The maxItems is a framework bound, not an HCP requirement."},"covers":{"type":"array","maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The High-sensitivity and custom categories the basis extends to; only these may be in `scope` (HCP 17.4). The maxItems is a framework bound, not an HCP requirement."},"establishedBy":{"type":"string","minLength":1,"maxLength":2048,"description":"The Authorization Service that established the delegation (HCP 17.2)."},"establishedAt":{"\$ref":"#/\$defs/Instant","description":"When the delegation was established (HCP 17.2)."}}},"EvidenceItem":{"type":"object","additionalProperties":true,"required":["role","type"],"description":"One evidence item (HCP 4.2.2). An item of a type the provider does not recognize is preserved and never raises assurance (HCP A.3). An item whose type is `verifiable-credential` MUST carry `credential`, an object with `@context`, `type`, `issuer` and `credentialSubject`, held whole as its issuer secured it (HCP 4.2.2). This rule is stated here and not as a schema conditional: the registry\'s Rust generator does not support `if`/`then`/`else`, so a validator does not check it.","properties":{"role":{"type":"string","enum":["content","supports"],"description":"`content`: the item\'s credential is the entry\'s content (VC Evidence profile). `supports`: the item backs content stated elsewhere in the entry (HCP 4.2.2)."},"type":{"type":"string","minLength":1,"maxLength":2048,"description":"The evidence type: `verifiable-credential`, or a URI (HCP 4.2.2, A.3)."},"credential":{"description":"The credential: for `verifiable-credential`, a W3C Verifiable Credential with `@context`, `type`, `issuer` and `credentialSubject`, whose own data model governs its contents (HCP 4.2.2, 14.2)."},"verification":{"type":"object","additionalProperties":true,"required":["result","at"],"description":"The provider\'s record of its most recent verification of the credential (HCP 4.2.2). Set only by the provider.","properties":{"result":{"type":"string","enum":["verified","failed"],"description":"The outcome."},"at":{"\$ref":"#/\$defs/Instant","description":"When the provider verified."},"by":{"type":"string","enum":["provider","trust-domain"],"description":"Who verified: the provider, or the Context Subject\'s trust domain under end-to-end encrypted storage (HCP 4.8). HCP\'s own values, carried verbatim."}}}}},"Directive":{"type":"object","additionalProperties":true,"required":["directiveId","action","effect","text","setBy","createdAt"],"description":"What a client may do with context it received, or on the Context Subject\'s behalf (HCP 6.4). A directive only narrows: it never authorizes a disclosure the grant does not. Where two that apply disagree, `deny` prevails over `ask-first`, and `ask-first` over `permit` (HCP 6.4).","properties":{"directiveId":{"\$ref":"#/\$defs/Urn","description":"Stable for the life of the directive (HCP 6.4)."},"action":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^(share|sign|transact|[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+)\$","description":"What the directive governs: `share` (passing received context to another agent), `sign` (signing, agreeing to or committing to anything on the Context Subject\'s behalf), `transact` (spending, buying or entering a contract on their behalf), or an absolute URI naming another action (HCP 6.4, A.3). A client MUST NOT treat an action it does not recognize as a permission; it reads the directive from `text`. The pattern admits the slug or an absolute URI\'s outline only: it carries no `format: uri`, which would refuse every slug, so checking that a custom value is a well-formed absolute URI, as HCP\'s prose requires (HCP A.3), is the consumer\'s check."},"effect":{"type":"string","enum":["deny","ask-first","permit"],"description":"`deny`: the client MUST NOT take the action. `ask-first`: the client MUST obtain the Context Subject\'s confirmation each time before taking it. `permit`: the client may take it without asking (HCP 6.4). HCP\'s own values, carried verbatim."},"text":{"type":"string","minLength":1,"maxLength":4096,"description":"The directive in the Context Subject\'s words (HCP 6.4). A client presents it to a model as data, never as instructions (HCP 7.4). The maxLength is a framework bound, not an HCP requirement."},"categories":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories whose context the directive governs; absent means every category, held now or later (HCP 6.4). The maxItems is a framework bound, not an HCP requirement."},"operators":{"type":"array","minItems":1,"maxItems":256,"items":{"type":"string","minLength":1,"maxLength":2048},"description":"The Client Operators the directive applies to, each a DNS domain or an operator identifier, matched as for standing rules; absent means every operator (HCP 6.4, 6.3). The maxItems is a framework bound, not an HCP requirement."},"setBy":{"type":"string","minLength":1,"maxLength":2048,"description":"Set by the provider: `context-subject`, or the `delegationId` of the delegate who set it (HCP 6.4, 6.3)."},"createdAt":{"\$ref":"#/\$defs/Instant","description":"Set by the provider: when the directive was set (HCP 6.4)."}}},"StandingRule":{"type":"object","additionalProperties":true,"required":["ruleId","effect","setBy","createdAt"],"description":"A deny rule the Context Subject sets across every grant, present and future (HCP 6.3). A standing rule never widens access. It carries `operators`, `requires`, or both: `operators` may be absent only where `requires` is present (HCP 6.3). HCP\'s own standing-rule schema checks that rule with an `anyOf` of the two `required` clauses; in this shared definition it is not checked by the schema, so that the type stays fully typed in every generated library. The hcp/rules/set request checks it at its payload root, where the rule is written; a provider never holds or returns a rule that breaks it, and hcp/import refuses an export holding one with `malformedRequest`.","properties":{"ruleId":{"\$ref":"#/\$defs/Urn","description":"Stable for the life of the rule (HCP 6.3)."},"effect":{"type":"string","enum":["deny"],"description":"`deny`, the only effect in HCP 2.0-draft-3 (HCP 6.3). Set by the provider."},"operators":{"type":"array","minItems":1,"maxItems":256,"items":{"type":"string","minLength":1,"maxLength":2048},"description":"The Client Operators the rule applies to (HCP 3.2.8, 6.3). A DNS domain matches every operator whose identifier\'s host is that domain or a subdomain of it; any other value matches one operator identifier exactly. Absent means every operator, which is allowed only with `requires`. The maxItems is a framework bound, not an HCP requirement."},"requires":{"type":"array","minItems":1,"maxItems":64,"items":{"\$ref":"#/\$defs/Uri"},"description":"Client conformance claims (HCP 18.1). Where present, the rule denies only clients of the named operators that do not make every claim listed (HCP 6.3). The maxItems is a framework bound, not an HCP requirement."},"categories":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/Category"},"description":"The categories the rule applies to. Absent means every category, held now or later (HCP 6.3). The maxItems is a framework bound, not an HCP requirement."},"setBy":{"type":"string","minLength":1,"maxLength":2048,"description":"Set by the provider: `context-subject`, or the `delegationId` of the delegate who set it (HCP 6.3, 17.2)."},"createdAt":{"\$ref":"#/\$defs/Instant","description":"Set by the provider: when the rule was set (HCP 6.3)."}}},"Uri":{"type":"string","format":"uri","minLength":1,"maxLength":2048,"pattern":"^[a-zA-Z][a-zA-Z0-9+.-]*:\\\\S+\$","description":"An absolute URI with no whitespace, as HCP writes every custom value at an extension point (HCP A.3)."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
  maxDocumentBytes: 14680064,
);
